mapper.select:
SELECT FROM ddc_app WHERE tenant_id = #{tenantId} AND deleted_at IS NULL AND biz_code = #{bizCode}
AND (lower(app_code) LIKE lower(concat('%', #{appCodeKeyword}, '%')) OR lower(app_name) LIKE lower(concat('%', #{appNameKeyword}, '%')))
AND enabled = #{enabled} ORDER BY app_code, id

mapper.sql:
a.tenant_id = #{tenantId} AND a.deleted_at IS NULL
AND a.biz_code = #{bizCode}
AND (lower(a.app_code) LIKE lower(concat('%', #{keyword}, '%'))
    OR lower(a.app_name) LIKE lower(concat('%', #{keyword}, '%')))
AND a.enabled = #{enabled}

    AND EXISTS (SELECT 1 FROM ddc_namespace_env_app b JOIN ddc_namespace n
                 ON n.tenant_id = b.tenant_id AND n.id = b.namespace_id
                WHERE b.tenant_id = a.tenant_id AND b.app_id = a.id AND b.env_code = #{env}
                  AND b.enabled = true AND b.deleted_at IS NULL AND n.enabled = true AND n.deleted_at IS NULL
                  AND n.biz_code = a.biz_code AND n.namespace_code = #{namespaceCode})

mapper.update:
UPDATE ddc_app SET deleted_at = CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
        version = version + 1, update_user_id = #{et.updateUserId}, update_time = #{et.updateTime}
        WHERE tenant_id = #{et.tenantId} AND id = #{et.id} AND version = #{et.version} AND deleted_at IS NULL
